sealed class Result {
    class Success(val value: Int) : Result()
    class Failure(val message: String) : Result()
}

fun handleResult(result: Result): String {
    return when (result) {
        is Result.Success -> "Success: ${result.value}"
        is Result.Failure -> "Error: ${result.message}"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testSuccess() {
        Assert.assertEquals("Success: 42", handleResult(Result.Success(42)))
    }

    @Test
    fun testSuccessZero() {
        Assert.assertEquals("Success: 0", handleResult(Result.Success(0)))
    }

    @Test
    fun testFailure() {
        Assert.assertEquals("Error: Sensor timeout", handleResult(Result.Failure("Sensor timeout")))
    }

    @Test
    fun testFailureDifferentMessage() {
        Assert.assertEquals("Error: Connection lost", handleResult(Result.Failure("Connection lost")))
    }

    @Test
    fun testSuccessProperty() {
        val s = Result.Success(100)
        Assert.assertEquals(100, s.value)
    }

    @Test
    fun testFailureProperty() {
        val f = Result.Failure("Oops")
        Assert.assertEquals("Oops", f.message)
    }
}
